    total = sum(max(0.0, float(t.get('occupancy') if t.get('occupancy') is not None else 1.0)) for t in sites)
    v = s.get('lattice', {}).get('volume_A3')
    if v is not None and math.isfinite(v) and v > 0 and total > 0:
        return float(v / total)
    v = s.get('volume_per_atom_A3')
    return float(v) if v is not None and math.isfinite(v) and v > 0 else 0.0

def feature(s):
    v = s.get('lattice', {}).get('volume_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    for t in s.get('sites', []):
        r = props.get(t.get('element'), {}).get('covalent_radius_A')
        o = t.get('occupancy')
        o = 1.0 if o is None else max(0.0, float(o))
        if r is not None and math.isfinite(r) and r > 0:
            total += o * r * r * r
    return float(4.0 * math.pi * total / (3.0 * v))

def feature(s):
    v = s.get('lattice', {}).get('volume_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    for t in s.get('sites', []):
        z = props.get(t.get('element'), {}).get('valence_electrons')
        o = t.get('occupancy')
        o = 1.0 if o is None else max(0.0, float(o))
        if z is not None and math.isfinite(z):
            total += o * z
    return float(total / v)

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    nearest = [math.inf] * n
    for b in s.get('neighbors', []):
        i = b.get('i', -1)
        d = b.get('distance_A')
        if 0 <= i < n and d is not None and math.isfinite(d) and d > 1e-8:
            nearest[i] = min(nearest[i], d)
    total = 0.0
    first = 0.0
    second = 0.0
    for i, t in enumerate(sites):
        if math.isfinite(nearest[i]):
            o = t.get('occupancy')
            o = 1.0 if o is None else max(0.0, float(o))
            total += o
            first += o * nearest[i]
            second += o * nearest[i] ** 2
    if total <= 0 or first <= 0:
        return 0.0
    mean = first / total
    return float(math.sqrt(max(0.0, second / total - mean * mean)) / mean)

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    occ = [max(0.0, float(t.get('occupancy') if t.get('occupancy') is not None else 1.0)) for t in sites]
    nearest = [math.inf] * n
    for b in s.get('neighbors', []):
        i = b.get('i', -1)
        d = b.get('distance_A')
        if 0 <= i < n and d is not None and math.isfinite(d) and d > 1e-8:
            nearest[i] = min(nearest[i], d)
    coord = [0.0] * n
    for b in s.get('neighbors', []):
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and math.isfinite(d) and d > 1e-8 and d <= 1.6 * nearest[i]:
            coord[i] += occ[j] * math.exp(1.0 - (d / nearest[i]) ** 6)
    total = sum(occ)
    if total <= 0:
        return 0.0
    mean = sum(occ[i] * coord[i] for i in range(n)) / total
    if mean <= 0:
        return 0.0
    variance = sum(occ[i] * (coord[i] - mean) ** 2 for i in range(n)) / total
    return float(math.sqrt(max(0.0, variance)) / mean)

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    occ = [max(0.0, float(t.get('occupancy') if t.get('occupancy') is not None else 1.0)) for t in sites]
    amounts = {}
    for i, t in enumerate(sites):
        e = t.get('element')
        amounts[e] = amounts.get(e, 0.0) + occ[i]
    total = sum(occ)
    if total <= 0:
        return 0.0
    baseline = 1.0 - sum((a / total) ** 2 for a in amounts.values())
    nearest = [math.inf] * n
    for b in s.get('neighbors', []):
        i = b.get('i', -1)
        d = b.get('distance_A')
        if 0 <= i < n and d is not None and math.isfinite(d) and d > 1e-8:
            nearest[i] = min(nearest[i], d)
    num = 0.0
    den = 0.0
    for b in s.get('neighbors', []):
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and math.isfinite(d) and d > 1e-8 and d <= 1.6 * nearest[i]:
            w = occ[i] * occ[j] * math.exp(1.0 - (d / nearest[i]) ** 6)
            den += w
            if sites[i].get('element') != sites[j].get('element'):
                num += w
    return float(num / den - baseline) if den > 0 else 0.0
